select
sum(stock_quantity) as maintainCount
from tb_material where stack_id = #{stackId}

select
distinct batch
from tb_material where stack_id = #{stackId}

select
distinct material_code as materialCode
from tb_material where stack_id = #{stackId}

select
distinct tobacco_year as tobaccoYear
from tb_material where material_code = #{materialCode}
and stack_id = #{stackId}
